from collections import OrderedDict
from typing import List

class LoadBalancer:
    """目标编号 1..n。每个目标用 OrderedDict 记录其上的连接，最左边是最久未使用的。"""

    def __init__(self, num_targets: int, max_conn: int = float('inf')):
        self.n = num_targets
        self.max_conn = max_conn
        self.on = {t: OrderedDict() for t in range(1, num_targets + 1)}  # target -> {conn_id: True}
        self.conn = {}        # conn_id -> (user, obj, target)
        self.sticky = {}      # obj -> target
        self.healthy = set(range(1, num_targets + 1))

    def _pick(self) -> int:
        # 活跃连接最少的健康目标，同数取编号小的
        return min(self.healthy, key=lambda t: (len(self.on[t]), t), default=-1)

    def _evict_lru(self, t: int) -> None:
        cid, _ = self.on[t].popitem(last=False)
        _, obj, _ = self.conn.pop(cid)
        if self.sticky.get(obj) == t and not any(self.conn[c][1] == obj for c in self.on[t]):
            del self.sticky[obj]

    def connect(self, cid: str, user: str, obj: str) -> str:
        t = self.sticky.get(obj)
        if t not in self.healthy:
            t = self._pick()
        if t == -1:
            return f"{cid} {user} -1"          # 没有健康目标
        if len(self.on[t]) >= self.max_conn:
            self._evict_lru(t)
        self.on[t][cid] = True
        self.conn[cid] = (user, obj, t)
        self.sticky[obj] = t
        return f"{cid} {user} {t}"

    def disconnect(self, cid: str) -> None:
        if cid in self.conn:
            _, _, t = self.conn.pop(cid)
            self.on[t].pop(cid, None)

    def shutdown(self, t: int) -> List[str]:
        self.healthy.discard(t)
        moved = list(self.on[t])               # 按连接先后重新路由
        self.on[t].clear()
        out = []
        for cid in moved:
            user, obj, _ = self.conn.pop(cid)
            if self.sticky.get(obj) == t:
                del self.sticky[obj]
            out.append(self.connect(cid, user, obj))
        return out


def route_requests(num_targets: int, max_conn: int, requests: List[str]) -> List[str]:
    lb, out = LoadBalancer(num_targets, max_conn), []
    for req in requests:
        p = [x.strip() for x in req.split(",")]
        if p[0] == "CONNECT":
            out.append(lb.connect(p[1], p[2], p[3]))
        elif p[0] == "DISCONNECT":
            lb.disconnect(p[1])
        elif p[0] == "SHUTDOWN":
            out.extend(lb.shutdown(int(p[1])))
    return out
